const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, ImageRun, AlignmentType, BorderStyle, ShadingType, PageBreak, TableOfContents, Footer, PageNumber, LevelFormat } = require('docx');
process.chdir(require('path').join(__dirname,'..'));
